            # 防篡改摘要链：旧记录缺链时连同既有事件一起按顺序补算
            # （不改动任何事件正文）；链已存在时严格加载已验通既有段，
            # 此处对追加后的完整事件序列重算，与新事件一次原子落盘。
            count, head = compute_chain_head(existing)
            data["chain"] = {
                "algorithm": CHAIN_ALGORITHM,
                "head": head,
                "count": count,
            }
